// grow_with_claudinite task: growth-dedup — the growth lifecycle's PRUNING stage
// (per-project-scheduling DESIGN §6). Prunes local-pack items the canon now
// covers, keeping items the canon states too generally; opens a PR against the
// default branch for the owner to approve. Worker: task.md.
//
// The old fleet's `relevantCanonChanged` becomes the `sharedMount` signal — a
// declared pack's vendored files moving is the local echo of "the canon this repo
// mounts changed" — and the weekly re-check crutch retires: a quiet repo with no
// local packs skips.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-dedup',
  frequency: 'daily+1h',           // the 05:00 slot — prunes against the merged/mounted canon, after promote (DESIGN §2)
  precondition_signals: ['localPacks', 'sharedMount', 'commits'],
  agent_model: 'opus',                   // proving the canon genuinely covers a local item — and telling coverage from "stated too generally" — is a judgment call
  expected_outcome: 'open-pr',              // a wrongful prune deletes a real local lesson, so this keeps a HUMAN approval gate (never auto-merge)
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,            // proving canon coverage per local item — generous bound, extreme protection

  // Gate: the repo must actually track local packs (no local packs → nothing to
  // prune, self-skip). Given local packs, run when the mounted canon this repo
  // CARES about moved — a declared pack's vendored files changed (`sharedMount`),
  // which can newly cover a local item — or the repo's own local packs changed in
  // the window (a fresh local item to re-check against the canon). A quiet repo
  // with local packs but no relevant movement skips.
  precondition(signals) {
    const local = signals.localPacks ?? {};
    // `present` is null when the scheduler couldn't determine it; treat only an
    // explicit false as "definitely no local packs to prune".
    if (local.present === false) {
      return { run: false, reason: 'no local packs — nothing to prune' };
    }
    const changedPacks = signals.sharedMount?.changedPacks ?? [];
    const canonMoved = changedPacks.length > 0;
    const localChanged = local.changedInWindow === true;

    if (canonMoved) {
      return { run: true, reason: `declared pack(s) changed in the mounted canon: ${changedPacks.join(', ')} — local items may now be covered`, context: [`Re-check local items against these newly-changed canon packs: ${changedPacks.join(', ')}.`] };
    }
    if (localChanged) {
      return { run: true, reason: 'local packs changed in the window — re-check the fresh items against the mounted canon' };
    }
    return { run: false, reason: 'local packs present but no relevant canon or local movement in the window' };
  },
};

import growthExtract from './run_daily/growth-extract-new-instructions.mjs';
import growthDedup from './run_daily/growth-dedup-local-instructions.mjs';
import growthDiscoverPacks from './run_daily/growth-discover-packs.mjs';
import conversationExtract from './run_daily/conversation-extract.mjs';
import growthConfig from './config-check.mjs';
import dedupIntegrity from './dedup-integrity.mjs';

// Opt into the growth lifecycle: a repo declaring grow_with_claudinite contributes its
// hard-won lessons up to the Claudinite canon and prunes them back out once the canon
// owns them. This pack carries the MEMBER-side stages — extract, dedup, and the weekly
// pack-discovery pipeline — as ordinary independent run_daily tasks (no barriers). The
// central promote stage — lifting portable lessons up into the shared canon — is a
// home-only duty that runs centrally, outside this pack; its gate targets exactly the
// members that declare THIS pack, minus any member whose entry sets config.promote:
// false (the promotion opt-out; extraction and dedup stay local either way).
//
// The pack also owns the CONVERSATION lifecycle: merge-to-main's capture step pushes
// each merged session's conversation onto the orphan conversation-logs branch
// (capture-log.mjs, in-session — it needs the live transcript), and the
// conversation-extract run_daily task (conversation-extract.md) mines those pushed
// logs with growth-extract's access model — the logs branch is in the repo, so reading
// it, committing lessons to local packs, and pruning aged logs are plain local git;
// only posting the short summary behind each extracted rule on its issue uses the
// GitHub MCP tools — pruning logs past config.retention_days.
//
// growth-discover-packs is the weekly pack-discovery pipeline: for the member it's
// handed it manifests the stack, suggests a pack for each unhomed technology, populates
// it with distilled rules/checks, and opens one canon PR per pack. It runs centrally
// (home session, fleet token) like every worker, but is scheduled the regular way.
//
// A declared pack (no fingerprint), seeded like tidy-repo: --init seeds it into every
// new repo, the one-time grow-with-claudinite-seed migration seeds the existing fleet,
// and baselining never re-adds it — so removing it is a durable opt-out.
export default {
  id: 'grow_with_claudinite',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: null,
  rules: [growthConfig, dedupIntegrity],
  questions: [{
    id: 'retention',
    prompt: 'How many days should a captured conversation log stay on the conversation-logs branch before the conversation-extract retention prune deletes it? The floor is the rethink window — extraction wants ~a week of hindsight; 10 is the recommended value.',
    distill: 'set config.retention_days on this entry to the agreed positive integer; until it is set, the prune deletes nothing (capture-only adoption)',
  }],
  run_daily: [growthExtract, growthDedup, growthDiscoverPacks, conversationExtract],
};

