import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { WORKER_DOC_PAIRS } from './worker-doc-pair.mjs';

// The drift guard over the migration's forked worker docs (see worker-doc-pair.mjs
// for the pairs and why the fork is forced). One-directional by design:
//
//   legacy edited, task NOT  ->  BLOCK. The task doc is the LIVE worker on every
//     cutover repo. A rule added only to the legacy doc reaches no cutover run —
//     it looks landed, and the routine keeps making the mistake the rule forbids.
//     This is not hypothetical: the dedup anti-growth discipline landed on
//     dedup.md alone and a cutover repo's dedup run then grew the local pack it
//     was pruning, exactly as the un-ported rule forbade.
//
//   task edited, legacy NOT  ->  fine, no finding. The legacy planner is being
//     retired at Phase 4; leaving it behind costs a shrinking set of pre-cutover
//     repos a refinement, and forcing a back-port would keep a dying doc alive.
//
// Home-only by declaration: canon-curation is declared solely in the canon repo,
// where these source trees exist. Relevance-first beyond that — a pair whose
// either side is gone (retired, or Phase 4 underway) is skipped, so the guard
// dies quietly with the tree it watches.
const rule = {
  id: 'worker-doc-pair-drift',
  severity: 'blocking',
  scope: 'work',
  doc: 'docs/per-project-scheduling/MIGRATION.md',
  description: 'An edit to a legacy run_daily worker doc also lands in the tasks/ worker doc it was forked into',
  why: 'the task doc is the live worker on every cutover repo — a rule added only to the legacy doc looks landed but reaches no cutover run, so the routine keeps making the mistake the rule forbids',

  run(work) {
    if (work.onDefaultBranch()) return [];
    const changed = new Set(work.changedFiles);
    return WORKER_DOC_PAIRS
      .filter(({ legacy, task }) =>
        changed.has(legacy) && !changed.has(task) && work.exists(legacy) && work.exists(task))
      .map(({ legacy, task }) => finding(rule, {
        file: legacy,
        what: `edited without its forked counterpart ${task}`,
        fix: `port the same change into ${task} (in that doc's own per-repo wording) — or, if it genuinely applies to the legacy dispatch path only, accept this rule on ${legacy} with the reason`,
      }));
  },
};

export default rule;

