import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, dirname, resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { makeRepo, cleanup } from '../../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../../engine/checks/helpers/repo-context.mjs';
import { runRule } from '../../../../engine/checks/helpers/work.mjs';
import workerDocDrift from './worker-doc-drift.mjs';
import { WORKER_DOC_PAIRS, UNPAIRED_LEGACY_WORKERS } from './worker-doc-pair.mjs';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '../../../..');

// The pair that caused the incident this rule exists for — reused as the fixture
// so the test reads as the failure it prevents.
const LEGACY = 'packs/grow_with_claudinite/dedup.md';
const TASK = 'packs/grow_with_claudinite/tasks/growth-dedup/task.md';

const run = (root) => runRule(workerDocDrift, buildContext({ root }));
const bothSides = { [LEGACY]: '# Dedup (fleet)\n', [TASK]: '# Dedup (per repo)\n' };

test('worker-doc-pair-drift: flags a legacy worker doc edited without its task counterpart', () => {
  const root = makeRepo({
    base: bothSides,
    changed: { [LEGACY]: '# Dedup (fleet)\n\nA dedup edit never grows the pack.\n' },
    commitMsg: 'dedup: forbid the growth failure Refs #1',
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].severity, 'blocking');
    assert.equal(findings[0].file, LEGACY);
    assert.match(findings[0].what, /without its forked counterpart/);
    assert.match(findings[0].fix, new RegExp(TASK.replace(/\//g, '\\/')));
  } finally { cleanup(root); }
});

test('worker-doc-pair-drift: silent when the same change lands on both sides', () => {
  const root = makeRepo({
    base: bothSides,
    changed: {
      [LEGACY]: '# Dedup (fleet)\n\nA dedup edit never grows the pack.\n',
      [TASK]: '# Dedup (per repo)\n\nA dedup edit never grows the pack.\n',
    },
    commitMsg: 'dedup: forbid the growth failure on both workers Refs #1',
  });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

