import { WORKER_DOC_PAIRS, UNPAIRED_LEGACY_WORKERS } from './worker-doc-pair.mjs';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '../../../..');

// The pair that caused the incident this rule exists for — reused as the fixture
// so the test reads as the failure it prevents.
const LEGACY = 'packs/grow_with_claudinite/dedup.md';
const TASK = 'packs/grow_with_claudinite/tasks/growth-dedup/task.md';

const run = (root) => runRule(workerDocDrift, buildContext({ root }));
