      [LEGACY]: '# Dedup (fleet)\n\nA dedup edit never grows the pack.\n',
      [TASK]: '# Dedup (per repo)\n\nA dedup edit never grows the pack.\n',
    },
    commitMsg: 'dedup: forbid the growth failure on both workers Refs #1',
  });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('worker-doc-pair-drift: one-directional — a task-only edit is fine (legacy is being retired)', () => {
  const root = makeRepo({
    base: bothSides,
    changed: { [TASK]: '# Dedup (per repo)\n\nRefined for the executor.\n' },
    commitMsg: 'dedup task: refine the dispatch note Refs #1',
  });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('worker-doc-pair-drift: a retired pair (legacy deleted) is skipped, not flagged', () => {
  // Phase 4 deletes run_daily/: the deletion itself changes the legacy path, but
  // with no legacy doc left on disk there is nothing to keep in sync — the guard
