  try {
    deletePath(root, LEGACY, 'retire the legacy dedup worker Refs #1');
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('worker-doc-pair-drift: silent on the default branch', () => {
  const root = makeRepo({ base: bothSides });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

// --- the pair list is data: prove it still matches the repo -------------------

// Every worker doc a run_daily unit declares, resolved to a repo-relative path.
// `worker:` is written repo-root-relative in the canon packs and pack-relative in
// canon-curation, so both forms are accepted — the same two the planner accepts.
const declaredLegacyWorkers = () => {
  const packRoots = [
    ...readdirSync(join(REPO, 'packs')).map((p) => join(REPO, 'packs', p)),
